function tradeCost({price,shares,discount=1,minimum=20,type='stock',rates={stock:.003,etf:.001,dayTrade:.0015}}){if(!finite(price,0.01)||!finite(shares,1)||!finite(discount,0,1)||!finite(minimum,1,1000))throw RangeError('請確認價格、股數、折扣與最低手續費');const rate=rates[type];if(!finite(rate,0,.01))throw RangeError('商品類型費率無效');const fee=Math.max(minimum,Math.floor(price*shares*.001425*discount)),tax=Math.floor(price*shares*rate),cost=fee*2+tax;return{fee,tax,cost,breakEvenPct:cost/(price*shares)*100}}
