(()=>{const D=window.SIM_HISTORY,S=window.HistoricalSimulation,app=document.getElementById('app');let chart;const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=x=>Number(x).toLocaleString('zh-TW',{maximumFractionDigits:0}),pct=x=>`${(+x).toFixed(2)}%`,k=(a,b)=>`<article class="kpi-card"><span>${a}</span><strong>${b}</strong></article>`;function plot(el,labels,datasets){chart?.destroy();chart=new Chart(el,{type:'line',data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom'}}}})}function view(){if(location.hash!=='#simulation')return;app.innerHTML=`<div class="wrap"><p class="eyebrow">08 / 歷史學習模擬</p><h1>用真實市場歷史練習</h1><p>資料為台灣加權股價指數月平均，不含股息與交易成本；過去表現不代表未來，不是標的推薦。</p><div class="card"><div class="actions mode-tabs" role="group"><button id="mode-a" aria-pressed="true">歷史事件闖關</button><button id="mode-b" class="button-secondary" aria-pressed="false">自由區間回測</button></div><div id="panel"></div></div><p class="tiny">國發會「景氣指標及燈號」OGL-1，資料集 6099，${D.range.startYm}–${D.range.endYm}。<a href="https://data.gov.tw/dataset/6099" target="_blank" rel="noopener">官方來源</a></p></div>`;document.getElementById('mode-a').onclick=()=>mode('a');document.getElementById('mode-b').onclick=()=>mode('b');mode('a')}function mode(x){let a=document.getElementById('mode-a'),b=document.getElementById('mode-b');a.classList.toggle('button-secondary',x!=='a');b.classList.toggle('button-secondary',x!=='b');a.setAttribute('aria-pressed',String(x==='a'));b.setAttribute('aria-pressed',String(x==='b'));x==='a'?scenario():free()}function scenario(){let p=document.getElementById('panel');p.innerHTML=`<h2>模式 A｜歷史事件闖關</h2><label>選擇情境<select id="sc">${D.scenarios.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`)}</select></label><label>每月投入<input id="sm" type="number" min="0" value="3000"></label><p id="sd"></p><p id="sp"></p><div class="actions" id="ops"><button id="go">繼續定期定額</button><button id="pause" class="button-secondary">本月暫停扣款</button><button id="sell" class="button-secondary">全部賣出空手觀望</button><button id="buy" class="button-secondary">重新買回並扣款</button><button id="all" class="button-secondary">一鍵以定期定額跑完剩餘月份</button><button id="reset" class="button-secondary">重設情境</button></div><p id="status" role="status"></p><div id="event"></div><div class="chart-box"><canvas id="simchart"></canvas></div><div id="metrics"></div>`;let step=0,actions=[];const sel=document.getElementById('sc'),range=()=>S.sliceMonths(D.monthlySeries,current().startYm,current().endYm),current=()=>D.scenarios.find(x=>x.id===sel.value);const storageKey=()=>`stepwise-sim-${sel.value}`;
function restore(){
  step=0;
  actions=[];
  try{
    const saved=JSON.parse(localStorage.getItem(storageKey()));
    if(Array.isArray(saved?.actions)){
      actions=saved.actions.slice(0,range().length);
      step=actions.length;
    }
  }catch{}
  paint();
}
function save(){localStorage.setItem(storageKey(),JSON.stringify({step,actions}))}
function paint(){let s=current(),m=range(),part=m.slice(0,step),holding=true;for(const x of actions.slice(0,step)){if(x==='sell')holding=false;if(x==='buy')holding=true}document.getElementById('sd').textContent=s.summary+' '+s.learningPoint;document.getElementById('sp').textContent=part.length?`${part.at(-1).ym}｜指數 ${money(part.at(-1).value)} 點｜單月漲跌 ${S.monthlyChange(D.monthlySeries,D.monthlySeries.findIndex(x=>x.ym===part.at(-1).ym)).toFixed(2)}%｜目前第 ${step} / ${m.length} 期`:`${s.startYm} 至 ${s.endYm}（共 ${m.length} 個月｜目前第 0 / ${m.length} 期）`;const done=step>=m.length;['go','pause','all'].forEach(id=>document.getElementById(id).disabled=done);document.getElementById('sell').disabled=done||!holding;document.getElementById('buy').disabled=done||holding;document.getElementById('status').textContent=done?'情境模擬完成，可重設後重新開始。':'';if(!part.length){chart?.destroy();chart=null;document.getElementById('metrics').innerHTML='';document.getElementById('event').innerHTML='';return}let r=S.simulate(part,{monthly:+sm.value||0,actions:actions.slice(0,step)}),benchmarkInvested=(+sm.value||0)*part.length,br=benchmarkInvested?100*(r.benchmarkFinal/benchmarkInvested-1):0,last=part.at(-1),ev=s.events.find(x=>x.ym===last.ym);document.getElementById('event').innerHTML=ev?`<article class="event-card"><b>${esc(ev.ym)}｜${esc(ev.title)}</b><p>${esc(ev.note)}</p></article>`:'';plot(simchart,part.map(x=>x.ym),[{label:'你的操作資產',data:r.rows.map(x=>x.userValue),borderColor:'#0F766E'},{label:'全程定期定額',data:r.rows.map(x=>x.benchmarkValue),borderColor:'#B91C1C'},{label:'累計投入本金',data:r.rows.map(x=>x.principal),borderColor:'#92400E'}]);document.getElementById('metrics').innerHTML=`<div class="kpi-columns"><section><h3>你的操作</h3><div class="kpi-grid">${k('投入',`NT$ ${money(r.totalInvested)}`)}${k('市值',`NT$ ${money(r.finalValue)}`)}${k('報酬率',pct(r.returnPct))}${k('最大回撤',pct(100*r.maxDrawdown))}</div></section><section><h3>全程定期定額</h3><div class="kpi-grid">${k('投入',`NT$ ${money(benchmarkInvested)}`)}${k('市值',`NT$ ${money(r.benchmarkFinal)}`)}${k('報酬率',pct(br))}${k('最大回撤',pct(100*r.benchmarkMaxDrawdown))}</div></section></div><div class="delta-card">差額：市值 ${r.finalValue>=r.benchmarkFinal?'+':''}NT$ ${money(r.finalValue-r.benchmarkFinal)}；報酬率 ${pct(r.returnPct-br)}</div>`}function act(x){let m=range();if(step>=m.length)return;actions[step++]=x;save();paint()}function reset(){localStorage.removeItem(storageKey());restore()}
sel.onchange=restore;document.getElementById('go').onclick=()=>act('continue');document.getElementById('pause').onclick=()=>act('pause');document.getElementById('sell').onclick=()=>act('sell');document.getElementById('buy').onclick=()=>act('buy');document.getElementById('reset').onclick=reset;document.getElementById('all').onclick=()=>{let m=range();for(let i=step;i<m.length;i++)actions[i]='continue';step=m.length;save();paint()};restore()}function free(){let p=document.getElementById('panel');p.innerHTML=`<h2>模式 B｜自由區間回測</h2><div class="form-grid"><label>起始年月<input id="from" type="month" min="${D.range.startYm}" max="${D.range.endYm}" value="${D.range.startYm}"></label><label>結束年月<input id="to" type="month" min="${D.range.startYm}" max="${D.range.endYm}" value="${D.range.endYm}"></label><label>初始本金<input id="principal" type="number" min="0" value="0"></label><label>每月投入<input id="monthly" type="number" min="0" value="3000"></label></div><button id="calc">計算</button><div id="metrics"></div><div class="chart-box"><canvas id="simchart"></canvas></div>`;document.getElementById('calc').onclick=()=>{try{let m=S.sliceMonths(D.monthlySeries,from.value,to.value),r=S.simulate(m,{principal:+principal.value,monthly:+monthly.value});document.getElementById('metrics').innerHTML=`<div class="kpi-grid five">${k('總投入',`NT$ ${money(r.totalInvested)}`)}${k('期末市值',`NT$ ${money(r.finalValue)}`)}${k('總報酬率',pct(r.returnPct))}${k('年化估算',pct(r.annualizedPct))}${k('期間最大回撤',pct(100*r.maxDrawdown))}</div>`;plot(simchart,m.map(x=>x.ym),[{label:'資產市值',data:r.rows.map(x=>x.userValue)},{label:'累計投入本金',data:r.rows.map(x=>x.principal)}])}catch(e){metrics.textContent=e.message}}}window.addEventListener('hashchange',view);view()})();
